<script setup lang="ts">import {ref,onMounted} from 'vue';import {api} from '../../api';import {t} from '../../locales';import '../../styles/app.scss';const items=ref<any[]>([]);const active=ref('全部');const queryCategory=ref('');const tags=ref<any[]>([]);const loading=ref(true);const error=ref(false);const filters=['全部','BTC','ETH','山寨币','交易所','政策'];async function load(){loading.value=true;error.value=false;try{items.value=await api.news(queryCategory.value)}catch{error.value=true}finally{loading.value=false}}onMounted(async()=>{try{tags.value=await api.newsTags()}catch{}await load()});function choose(x:string){active.value=x;const tag=tags.value.find(t=>t.name===x||t.code===x||t.enName===x);queryCategory.value=x==='全部'?'':(tag?String(tag.id):x);load()}function detail(id:string){uni.navigateTo({url:'/pages/detail/news?id='+id})}</script>
<template><view class="flash-page"><view class="flash-filter"><scroll-view scroll-x class="flash-tabs"><view class="flash-tabs-inner"><text v-for="x in filters" :key="x" class="flash-tab" :class="{active:active===x}" @click="choose(x)">{{t(x)}}</text></view></scroll-view><text class="search-icon" @click="uni.navigateTo({url:'/pages/search/index'})">⌕</text></view><view v-if="loading" class="flash-state">{{t('加载中...')}}</view><view v-else-if="error" class="flash-state">{{t('加载失败，请重试')}}<button class="outline" @click="load">{{t('重试')}}</button></view><view v-else-if="!items.length" class="flash-state">{{t('暂无快讯')}}</view><view v-else class="flash-list"><view v-for="n in items" :key="n.id" class="flash-item" :class="n.level==='紧急'?'urgent':n.level==='要闻'?'important':'normal'" @click="detail(n.id)"><view class="flash-meta"><text class="level">{{t(n.level)}}</text><text>{{n.time}}</text></view><view class="flash-title">{{n.title}}</view><view class="flash-summary">{{n.summary || t('市场快讯与行情动态。')}}</view><view class="flash-foot"><view class="flash-source"><text class="source-dot">●</text><text>{{n.source}}</text><text class="tags">{{n.tags}}</text></view><text class="sentiment" :class="n.sentiment==='利好'?'up':n.sentiment==='利空'?'down':'muted'">{{t(n.sentiment)}}</text></view></view></view></view></template>
<style scoped>.flash-page{min-height:100vh;padding-bottom:120rpx;background:#fff;color:var(--cf-text)}.flash-filter{display:flex;align-items:center;gap:14rpx;padding:24rpx 28rpx;border-bottom:1rpx solid var(--cf-line)}.flash-tabs{flex:1;min-width:0;white-space:nowrap}.flash-tabs-inner{display:flex;gap:12rpx;width:max-content}.flash-tab{padding:9rpx 20rpx;background:#F1F5F9;border-radius:24rpx;color:var(--cf-muted);font-size:23rpx}.flash-tab.active{background:var(--cf-brand);color:#fff}.search-icon{flex:0 0 34rpx;color:var(--cf-muted);font-size:38rpx;text-align:center}.flash-list{padding:24rpx 28rpx}.flash-item{padding:0 0 26rpx 20rpx;margin-bottom:28rpx;border-left:4rpx solid var(--cf-line)}.flash-item.urgent{border-color:var(--cf-down)}.flash-item.important{border-color:var(--cf-brand)}.flash-meta,.flash-foot{display:flex;align-items:center;justify-content:space-between;color:var(--cf-soft);font-size:21rpx}.flash-meta{justify-content:flex-start;gap:14rpx}.level{padding:3rpx 9rpx;border-radius:5rpx;background:#F1F5F9;color:var(--cf-muted);font-weight:700}.urgent .level{background:#FEF2F2;color:var(--cf-down)}.important .level{background:#EFF6FF;color:var(--cf-brand)}.flash-title{margin:9rpx 0 7rpx;font-size:30rpx;line-height:1.4;font-weight:700}.flash-summary{overflow:hidden;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;color:var(--cf-muted);font-size:24rpx;line-height:1.55}.flash-foot{gap:10rpx;margin-top:14rpx}.flash-source{display:flex;align-items:center;gap:9rpx;min-width:0;overflow:hidden;white-space:nowrap}.source-dot,.tags{color:var(--cf-brand)}.sentiment{flex:none;padding:3rpx 8rpx;border-radius:5rpx;background:#F1F5F9;font-weight:700}.sentiment.up{background:#ECFDF5}.sentiment.down{background:#FEF2F2}.flash-state{padding:56rpx 28rpx;color:var(--cf-muted);text-align:center;font-size:22rpx}</style>
<style scoped>.flash-page{padding-top:calc(24rpx + var(--cf-safe-top))}</style>
